            for(int j=0; j<n; j++)
            {
                if(grid[i][j] == 1 and vis[i][j] == 0)
                {
                    dfs(i , j , v , vis, grid);
                    if(flag == 0)
                    {
                        v1 = v;
                        flag = 1;
                        v.clear();
                    }
                    else
                    {
                        v2 = v;
                    }
                }

            }

        }
        //printed just to check the co-ordinates****
        //for(auto it: v1)
        //{
        //    cout<<it.first<<" "<<it.second<<endl;
        //}
        //for(auto it: v2)
        //{
        //    cout<<it.first<<" "<<it.second<<endl;
        //}
        int ans = 1e9;


        for(auto it: v1)
        {
            int row1 = it.first;
            int col1 = it.second;

            for(auto itt: v2)
            {
                int row2 = itt.first;
                int col2 = itt.second;

                int dist = abs(row1 - row2) + abs(col1 - col2);
                dist--;
                ans = min(ans , dist);
            }
        }

        return ans;
    }
};

