class Solution {
public:
    int singleNumber(vector<int>& nums) {
        int n=arr.size();
        // Checking for edge cases
        if(n==1 || arr[0]!=arr[1]){
            return arr[0];
        }
        if(arr[n-1]!=arr[n-2]){
            return arr[n-1];
        }
        // Going for Binary search approach
        int low=1,high=n-2;
        while(low<=high){
            int mid=low+(high-low)/2;
            if(arr[mid]!=arr[mid-1] && arr[mid]!=arr[mid+1]){
                return arr[mid];
            }
            if((mid%2==1 && arr[mid]==arr[mid-1]) || (mid%2==0 && arr[mid]==arr[mid+1])){// In left half
                low=mid+1;
            }
            else{// In Right half
                high=mid-1;
            }
        }
        return -1;
    }
};
