class Solution {
public:
  int f(int curr,int prev,vector<int>& nums,int n){
			int t=nums[curr]+nums[prev];
			int i=lower_bound(nums.begin(),nums.end(),t)-nums.begin();
			if(i<n && nums[i]==t) return 1+f(i,curr,nums,n);
