solution_explanation:
# Approach
Idea is to delete an edge connecting a and b, and then find the minimum distance between a and b (without considering the deleted edge), this shortest path plus one is the size of the smallest loop having both nodes a and b. 
Repeat the same for each edge and return the the size of minimum loop.

# Complexity
- Time complexity: O(E^2)
<!-- Add your time complexity here, e.g. $$O(n)$$ -->

# Code
```
class Solution {
public:
    int f(int ind, unordered_map<int, vector<pair<int, int>>> &mp, int a, int b)
    {
        queue<pair<int, int>> q;
        unordered_map<int, int> vis;
        q.push({a, 0});
        vis[a]=1;
        while(!q.empty())
        {
            int curr = q.front().first;
            int dis = q.front().second;
            q.pop();
            for(auto &x: mp[curr])
            {
                if(x.second==ind || vis[x.first]==1)
                    continue;
                if(x.first == b)
                    return dis+1;
                q.push({x.first, dis+1});
                vis[x.first]=1;
            }
        }
        return 10000;
    }
    int findShortestCycle(int n, vector<vector<int>>& edges) {
        unordered_map<int, vector<pair<int, int>>> mp;
        for(int i=0; i<edges.size(); i++)
        {
            mp[edges[i][0]].push_back({edges[i][1], i});
            mp[edges[i][1]].push_back({edges[i][0], i});
        }
        int mn = 10000;
        for(int i=0; i<edges.size(); i++)
            mn = min(mn, f(i, mp, edges[i][0], edges[i][1]));
        if(mn>=10000)
            return -1;
        return mn+1;
    }
};
```

