        unordered_map<string, int> forbidden_word;
        for(auto it : forbidden)forbidden_word[it] = 1;
        int n = word.size();
        for(int i = 0; i<n; i++){
            string temp = "";
            for(int j = i; j<i+10 && j<n; j++){
                temp += word[j];
                if(forbidden_word.find(temp) != forbidden_word.end()) {
                    ends[j] = i;
                }
            }
        }

        int i = 0, j = 0;
        int ans = INT_MIN;
        while(j < n){

            if(ends[j] != -1){
                int st = ends[j];
                if(st < i){
                    ans = max(ans, j-i+1);
                }
                else{
                    i = st+1;
                    ans = max(ans, j-i+1);
                }
            }
            else ans = max(ans,j-i+1);
            j++;
        }
        return ans;
    }
};

