class Solution {
private:
    bool helper(vector<vector<int>>& grid, int row, int col, int num){
        int n = grid.size();
        if(num == n*n) return true;
        int i = row-2;
        int j = col+1;
        if(i>=0 && j<n && grid[i][j] == num) return helper(grid,i,j,num+1);

        i = row-2;
        j = col-1;
