        tweets[timer--] = {userId, tweetId};
    }

    vector<int> getNewsFeed(int userId) {
        vector<int> ans;
        for(auto it: tweets){
            if(it.second.first == userId || friends[userId].find(it.second.first)!=friends[userId].end())
