        j = col - 2;
        if(i<n && j>=0 && grid[i][j] == num) return methodNotFound(grid,i,j,num+1);

        return false;
    }
public:
    bool checkValidGrid(vector<vector<int>>& grid) {
        ios::sync_with_stdio(false);
        cin.tie(0);
        cout.tie(0);
