    int reversePairs(vector<int>& arr) {
      // merge sort -> modified merge function 
    int cnt=0;
    int n=arr.size();
    mergesort(arr,0,n-1,cnt);
    if(n<=1 or cnt==0)return 0;
    return cnt;

    }
};
