        vector<long long> ans(5,0);
        int sz=cds.size();
        set<pair<int,int>> s,black;
        for(int i=0;i<sz;++i){
            black.insert({cds[i][0],cds[i][1]});
        }
        for(int i=0;i<sz;++i){
            int x=cds[i][0],y=cds[i][1];
            // it can cover four squares
            // case 1
            if(x>0&&y>0){
                bool flag=true;
                int cnt=0;
                for(int dx=-1;dx<=0;++dx){
                    for(int dy=-1;dy<=0;++dy){
                        if(s.find({x+dx,y+dy})==s.end()){
                            if(black.find({x+dx,y+dy})!=black.end()){
                                cnt++;
                            } 
                        } else{
                            flag=false;
                            break;
                        } 
                    }
                }
                if(flag){
                    ans[cnt]++;
                }
            }
            // case 2
            if(x<m-1&&y>0){
                bool flag=true;
                int cnt=0;
                for(int dx=0;dx<=1;++dx){
                    for(int dy=-1;dy<=0;++dy){
                        if(s.find({x+dx,y+dy})==s.end()){
                            if(black.find({x+dx,y+dy})!=black.end()){
                                cnt++;
                            }
                        } else{
                            flag=false;
                            break;
                        } 
                    }
                }
                if(flag){
                    ans[cnt]++;
                }
            }
            // case 3
            if(x>0&&y<n-1){
                bool flag=true;
                int cnt=0;
                for(int dx=-1;dx<=0;++dx){
                    for(int dy=0;dy<=1;++dy){
                        if(s.find({x+dx,y+dy})==s.end()){
                            if(black.find({x+dx,y+dy})!=black.end()){
                                cnt++;
                            } 
                        } else{
                            flag=false;
                            break;
                        } 
                    }
                }
                if(flag){
                    ans[cnt]++;
                }
            }
            // case 4
            if(x<m-1&&y<n-1){
                bool flag=true;
                int cnt=0;
                for(int dx=0;dx<=1;++dx){
                    for(int dy=0;dy<=1;++dy){
                        if(s.find({x+dx,y+dy})==s.end()){
                            if(black.find({x+dx,y+dy})!=black.end()){
                                cnt++;
                            }
                        } else{
                            flag=false;
                            break;
                        } 
                    }
                }
                if(flag){
                    ans[cnt]++;
                }
            }
            // put in set
            s.insert({x,y});
        }
        ans[0]=(m-1)*1ll*(n-1)-ans[1]-ans[2]-ans[3]-ans[4];
        return ans;
    }
};
