# Code
```
class Solution {
public:
    int binaryS(vector<int>& v, int sz) {
        int l=0, r=sz, mid;
        while(l<r){
            mid=l+(r-l)/2;
            if(v[mid]<0) r=mid;
            else l=mid+1;
        }
        return r;  // Returns the index
        // The binaryS function is used to find the index where 
