                s=s.substring(1)+s.charAt(0); // first element is being shifted to last
                if(str2.compareTo(s)>0){        //if this lexo combo is smaller than previous
                    str2=s;                     //store smaller lexo combo
                } 
             }
             return str2;
        }     
    }
}
