class Solution {
    public int maxIceCream(int[] costs, int coins) {
        int [] arr = new int [100001];
        for(int x : costs)arr[x]++;
        int count = 0;
        int index = 1;
//If coins can buy all the ice-cream at ith index.
        while(index<100001 && coins>=index*arr[index]){
            coins-=index*arr[index];
            count+=arr[index];
            index++;
        }
//If coins can buy onyl some of the ice-creams at ith index.
        while(index<100001 && coins>=index){
            coins-=index;
            count++;
        }
        return count;
    }
}
```

# Using priority Queue
```
class Solution {
    public int maxIceCream(int[] costs, int coins) {
        PriorityQueue<Integer> pq = new PriorityQueue<Integer>(Collections.reverseOrder());
        int sum = 0;
        for(int x : costs){
            if(sum<=coins){
                sum+=x;
                pq.add(x);
            }else if(pq.peek()>x){
                sum = sum - pq.poll() + x;
                pq.add(x);
            }
        }
        while(sum>coins){
            sum-=pq.poll();
        }
        return pq.size();
    }
}
