class Solution {
    String convert(String s)
    {
        char prevCh = s.charAt(0);
        int prevCount = 1; //stores count of consecutive same digits
        StringBuilder ans = new StringBuilder();
        for (int i = 1; i < s.length(); i++)
        {
            char currCh = s.charAt(i);
