					diff: -3
					// Wildcard matching on s2[j]
                    val = 4 diff = -3+4 =1 increment j

						i: 4
						j: 2
						diff: 1
                         // Literal matching on s1[i]
                         decrement i-1 and increment i

                            i=5
                            j=2
                                diff==0 return true
                        dp[4][2][1] = true    
						return true
				    return dp[4][1][1000-3] = true
                return dp[3][1][0] = true

			i: 2
			j: 1
			diff: 2
