        DisjointSet(int n) {
            groupCount = n;
            maxSize = 1;
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        public int find(int a) {
            if (parent[a] != a) {
                parent[a] = find(parent[a]);
            }
            return parent[a];
        }

        public void union(int a, int b) {
            if (a == b) {
                return;
            }
            int pa = find(a);
            int pb = find(b);
            if (pa != pb) {
				// Improving the runtime for find operations by joining the small group to large one
                if (size[pb] < size[pa]) {
                    parent[pa] = pb;
                    size[pb] += size[pa];
                    maxSize = Math.max(maxSize, size[pb]);
                } else {
                    parent[pb] = pa;
                    size[pa] += size[pb];
                    maxSize = Math.max(maxSize, size[pa]);
                }
                groupCount--;
            }
        }

        public int[] getState() {
            return new int[]{groupCount, maxSize};
        }
    }
}

