```
class Solution {
    public String firstPalindrome(String[] words) {
        for (String s : words){
            StringBuilder sb = new StringBuilder();
            sb.append(s).reverse();

            if (s.equals(sb.toString())){
                return s;
            }
        }

        return "";
    }
}

// TC: O(n * k), SC: O(1)
// n -> length of words
// k -> length of longest string in words
