            while(lower.size() >= 2 && angle(lower.get(lower.size() - 2),lower.get(lower.size() - 1),trees[i]) < 0){
                 lower.pop();  
              }
            upper.push(trees[i]);
            lower.push(trees[i]);
        }


        Set<int[]> res= new HashSet<>(lower);
        res.addAll(upper);
        return res.toArray(new int[res.size()][]);
    }

