                stack.push(value2);
                stack.push(value1);
                stack.push(value);
            }else {
                stack.push(Integer.parseInt(operations[i]));
            }
        }

        System.out.println("Stack" + stack);

        int sum =0;
        while (!stack.isEmpty()){
            sum += stack.pop();
        }

        return sum;
    }
}
