class Solution {
    public int firstCompleteIndex(int[] arr, int[][] mat) {
        int ind=0;
        int m=mat.length,n=mat[0].length;
        int row[]=new int[m];
        int col[]=new int[n];
        boolean flag=true;;
        while(flag){
            int i=0;
            for(i=0;i<m;i++){
                int j=0;
                for(j=0;j<n;j++){
                    if(mat[i][j]==arr[ind]){
                        ind++;
                        row[i]++;
                        col[j]++;
                    }
                    if(row[i]==n || col[j]==m){
