class Solution {
    public int uniquePathsIII(int[][] grid) {

        int row = 0;
        int col = 0;

        //finding the starting square's row and column
        for(int i = 0; i < grid.length; i++) {
            for(int j = 0; j < grid[0].length; j++) {
                if(grid[i][j] == 1) {
                    row = i;
                    col = j;
                    break;
                }
            }
        }

        //boolean array named (used) is used to store the squares which have already been used
        //till now in a particular path

        boolean[][] used = new boolean[grid.length][grid[0].length];

        return count(grid, used, row, col);
    }

    int count(int[][] grid, boolean[][] used, int row, int col) {

        used[row][col] = true;

        //we have arrived at the ending square. Now, it might be possible, that the path we 
        //followed till here from starting position, does not contain all the 0 squares
        //therefore to decide this we call the isValid function
        //Also, it might happen that there's an obstacle on the same ending square, in this
        //case we won't find any path because the destination square is itself an obstacle
        //so we return 0. and to check this only we have put another 
        //condition grid[row][col] != -1

        if(grid[row][col] == 2) {
            if(isValid(used, grid) && grid[row][col] != -1) {
                used[row][col] = false;
                return 1;
            }
            used[row][col] = false;
            return 0;
        }

        //if we have arrived at an obstacle square, then return 0, because we can't obtain 
        //any further paths including this square, because this is an obstacle
        //while returning, unmark this square as used, i.e. mark it as unused

        if(grid[row][col] == -1) {
            used[row][col] = false;
            return 0;
        }

        int paths = 0;

        //DOWN
        if(row < grid.length - 1 && !used[row + 1][col]) {
            paths += count(grid, used, row + 1, col);
        }
        //RIGHT
        if(col < grid[0].length - 1 && !used[row][col + 1]) {
            paths += count(grid, used, row, col + 1);
        }
        //UP
        if(row > 0 && !used[row - 1][col]) {
            paths += count(grid, used, row - 1, col);
        }
        //LEFT
        if(col > 0 && !used[row][col - 1]) {
            paths += count(grid, used, row, col - 1);
        }

        //backtrack, mark the square as unused now!
        used[row][col] = false;

        return paths;
    }

    //to check whether the path which we have travelled from starting square to ending square
    //contains all the 0 squares in it or not. If the path does not contain all the 0 sqaures
    //then isValid return false, and we do not count this path and hence return 0 in the count
    //function.
    //if the path contains all the 0 squares, then isValid return true, and hence 
    //we count this path and hence in count function we return 1, as we got one path
    //which contains all the 0 squares.

    boolean isValid(boolean[][] used, int[][] grid) {

        for(int i = 0; i < used.length; i++) {
            for(int j = 0; j < used[0].length; j++) {
                if(grid[i][j] == 0) {
                    if(!used[i][j]) {
                        return false;
                    }
                }
            }
        }
        return true;
    }
}
