                break
        for i in range(N-1,-1,-1):
            if s[i] == '1':
                cnt1 += 1
            if cnt1 == c1//3:
                idx4 = i
                break
        for i in range(idx4-1,-1,-1):
            if s[i] == '1':
                idx3 = i
                break
        return ((idx2-idx1) * (idx4-idx3)) % MOD
